CREATE TABLE crm_companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,legal_name text,document text,email text,phone text,website text,city text,state text,company_type text NOT NULL DEFAULT 'prospect',status text NOT NULL DEFAULT 'active',notes text,created_by uuid REFERENCES profiles(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX idx_crm_companies_org_type ON crm_companies(organization_id,company_type,status) WHERE deleted_at IS NULL;
CREATE TABLE crm_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),company_id uuid REFERENCES crm_companies(id) ON DELETE SET NULL,name text NOT NULL,email text,phone text,role_title text,notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX idx_crm_contacts_org_company ON crm_contacts(organization_id,company_id) WHERE deleted_at IS NULL;
CREATE TABLE crm_opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),company_id uuid REFERENCES crm_companies(id) ON DELETE SET NULL,contact_id uuid REFERENCES crm_contacts(id) ON DELETE SET NULL,title text NOT NULL,stage text NOT NULL DEFAULT 'new' CHECK(stage IN ('new','qualified','proposal','negotiation','won','lost')),value numeric(14,2) NOT NULL DEFAULT 0,probability integer NOT NULL DEFAULT 0 CHECK(probability BETWEEN 0 AND 100),expected_close_date date,owner_id uuid REFERENCES profiles(id),source text,notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX idx_crm_opportunities_org_stage ON crm_opportunities(organization_id,stage,expected_close_date) WHERE deleted_at IS NULL;
CREATE TABLE sponsors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),company_id uuid REFERENCES crm_companies(id) ON DELETE SET NULL,name text NOT NULL,tier text,status text NOT NULL DEFAULT 'prospect',starts_at date,ends_at date,notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ad_campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),company_id uuid REFERENCES crm_companies(id) ON DELETE SET NULL,name text NOT NULL,placement text NOT NULL,landing_url text,desktop_media_id uuid REFERENCES media(id) ON DELETE SET NULL,mobile_media_id uuid REFERENCES media(id) ON DELETE SET NULL,starts_at timestamptz,ends_at timestamptz,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','active','paused','completed','cancelled')),impressions bigint NOT NULL DEFAULT 0,clicks bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_ad_campaigns_org_status ON ad_campaigns(organization_id,status,starts_at);
CREATE TABLE commercial_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),company_id uuid REFERENCES crm_companies(id) ON DELETE SET NULL,name text NOT NULL,description text,status text NOT NULL DEFAULT 'planning',budget numeric(14,2) NOT NULL DEFAULT 0,starts_at date,ends_at date,owner_id uuid REFERENCES profiles(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX idx_commercial_projects_org_status ON commercial_projects(organization_id,status) WHERE deleted_at IS NULL;
CREATE TABLE proposals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),company_id uuid REFERENCES crm_companies(id) ON DELETE SET NULL,opportunity_id uuid REFERENCES crm_opportunities(id) ON DELETE SET NULL,project_id uuid REFERENCES commercial_projects(id) ON DELETE SET NULL,number text NOT NULL,title text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','accepted','rejected','expired','cancelled')),total_value numeric(14,2) NOT NULL DEFAULT 0,valid_until date,content jsonb NOT NULL DEFAULT '{}'::jsonb,created_by uuid REFERENCES profiles(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,number));
CREATE TABLE contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),company_id uuid REFERENCES crm_companies(id) ON DELETE SET NULL,proposal_id uuid REFERENCES proposals(id) ON DELETE SET NULL,project_id uuid REFERENCES commercial_projects(id) ON DELETE SET NULL,number text NOT NULL,title text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','completed','cancelled','expired')),value numeric(14,2) NOT NULL DEFAULT 0,starts_at date,ends_at date,content jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,number));
ALTER TABLE crm_companies ENABLE ROW LEVEL SECURITY; ALTER TABLE crm_contacts ENABLE ROW LEVEL SECURITY; ALTER TABLE crm_opportunities ENABLE ROW LEVEL SECURITY; ALTER TABLE sponsors ENABLE ROW LEVEL SECURITY; ALTER TABLE ad_campaigns ENABLE ROW LEVEL SECURITY; ALTER TABLE commercial_projects ENABLE ROW LEVEL SECURITY; ALTER TABLE proposals ENABLE ROW LEVEL SECURITY; ALTER TABLE contracts ENABLE ROW LEVEL SECURITY;